// 1. C 语言内存泄漏示例
#include <stdlib.h>

void memory_leak_example() {
    while (1) {
        char *buf = malloc(1024);  // 每次分配 1KB
        // 忘记 free(buf)，内存持续增长
    }
}

// 修复：添加 free
void memory_fixed() {
    while (1) {
        char *buf = malloc(1024);
        // 使用 buf...
        free(buf);  // 释放内存
    }
}

// 2. Java 内存泄漏示例
public class LeakDemo {
    private static final List<byte[]> cache = new ArrayList<>();

    public void addToCache() {
        // 不断向 static list 添加数据，永远不会被 GC
        cache.add(new byte[1024 * 1024]); // 1MB
    }
}

// 3. Linux 排查命令
// valgrind --leak-check=full ./my_program
// top -p <pid>                    // 查看内存使用
// cat /proc/<pid>/status | grep VmRSS  // 物理内存占用
// pmap -x <pid>                   // 内存映射详情

// 4. Java 排查命令
// jmap -heap <pid>                // 堆内存概况
// jmap -dump:format=b,file=heap.bin <pid>  // 堆转储
// jstat -gcutil <pid> 1000        // GC 监控
